functions.stepHandDragPhysics:
function stepHandDragPhysics(body,target,dt,reduced=false){
  dt=Math.min(.034,Math.max(.001,dt));
  if(reduced){body.x=target.x;body.y=target.y;body.vx=body.vy=body.angle=body.tilt=0;body.scale=1;return body;}
  const stiffness=190,damping=23;
  body.vx+=(stiffness*(target.x-body.x)-damping*body.vx)*dt;
  body.vy+=(stiffness*(target.y-body.y)-damping*body.vy)*dt;
  body.x+=body.vx*dt;body.y+=body.vy*dt;
  // Keep rapid cross-screen gestures close enough to the hand to feel connected.
  const dx=target.x-body.x,dy=target.y-body.y,distance=Math.hypot(dx,dy);
  if(distance>65){body.x=target.x-dx/distance*65;body.y=target.y-dy/distance*65;}
  const ease=1-Math.exp(-14*dt);
  body.angle+=(Math.max(-12,Math.min(12,body.vx*.012))-body.angle)*ease;
  body.tilt+=(Math.max(-7,Math.min(7,-body.vy*.008))-body.tilt)*ease;
  body.scale+=(1.055+Math.min(.02,Math.hypot(body.vx,body.vy)/40000)-body.scale)*ease;
  return body;
}

functions.stepTableCardSlide:
function stepTableCardSlide(body,dt,bounds){
  dt=Math.max(0,dt);const speed=Math.hypot(body.vx,body.vy);
  if(speed>0){
    const elapsed=Math.min(dt,speed/TABLE_CARD_FRICTION),distance=speed*elapsed-TABLE_CARD_FRICTION*elapsed*elapsed/2;
    body.x+=body.vx/speed*distance;body.y+=body.vy/speed*distance;
    const remaining=Math.max(0,speed-TABLE_CARD_FRICTION*elapsed)/speed;body.vx*=remaining;body.vy*=remaining;
  }
  const spinDecay=Math.exp(-TABLE_CARD_SPIN_DRAG*dt);
  body.angle+=body.spin*(1-spinDecay)/TABLE_CARD_SPIN_DRAG;body.spin*=spinDecay;
  const edge=typeof bounds==='function'?bounds(body.angle):bounds;
  const x=Math.max(edge.left,Math.min(edge.right,body.x)),y=Math.max(edge.top,Math.min(edge.bottom,body.y));
  // A soft, lossy table-edge collision preserves a little rebound and spends spin.
  if(x!==body.x){if(body.vx*(body.x-x)>0)body.vx*=-.28;body.vy*=.85;body.spin*=.65;}
  if(y!==body.y){if(body.vy*(body.y-y)>0)body.vy*=-.28;body.vx*=.85;body.spin*=.65;}
  body.x=x;body.y=y;return body;
}

functions.stepTableCardDrag:
function stepTableCardDrag(drag,pointer,dt){
  const dx=pointer.x-drag.pointer.x,dy=pointer.y-drag.pointer.y;
  if(dt>0 && !window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches){
    const elapsed=Math.min(.1,dt),steps=Math.max(1,Math.ceil(elapsed/.008)),h=elapsed/steps;
    const vx=dx/dt,vy=dy/dt;
    for(let step=0;step<steps;step++){
      const arm=tableCardGrip(drag.grip.x,drag.grip.y,drag.rotation);
      const target=Math.max(-720,Math.min(720,(arm.x*vy-arm.y*vx)/(drag.inertia+arm.x*arm.x+arm.y*arm.y)*180/Math.PI));
      const decay=Math.exp(-h/.06),before=drag.spin;
      drag.spin=target+(before-target)*decay;
      drag.rotation+=target*h+(before-target)*.06*(1-decay);
    }
  }
  const arm=tableCardGrip(drag.grip.x,drag.grip.y,drag.rotation);
  return moveTitleCard(drag.node,pointer.x-arm.x,pointer.y-arm.y,drag.rotation);
}
